[CmdletBinding()]param([Parameter(Mandatory)][string]$BaseUri,[Parameter(Mandatory)][string]$TokenFile,[Parameter(Mandatory)][string]$ExpectedTarget)
$ErrorActionPreference='Stop';$base=$BaseUri.TrimEnd('/');$token=(Get-Content $TokenFile -Raw).Trim();$auth=@{Authorization="Bearer $token"}
function A([bool]$c,[string]$m){if(-not$c){throw "Phase 9B provider failed: $m"}}
function O($ids,$allow){Invoke-RestMethod "$base/v0/observe/deep" -Method Post -Headers $auth -ContentType 'application/json' -Body (@{perspective='server_authoritative';domains=@('player','providers');includeProviderData=$true;allowReadEffects=$allow;providerIds=$ids;providerQuery=@{probe='phase9b'};budgets=@{maxProviders=8;maxProviderBytes=16384;maxTotalProviderBytes=65536;providerTimeoutMs=100;maxResponseBytes=262144}}|ConvertTo-Json -Depth 20 -Compress)}
$safe=O @('mine_craft_protocol:safe','mine_craft_protocol:lazy') $false; A (@($safe.providers|Where-Object -Property providerId -eq 'mine_craft_protocol:safe')[0].status -eq 'completed') 'safe'; A (@($safe.providers|Where-Object -Property providerId -eq 'mine_craft_protocol:lazy')[0].status -eq 'skipped') 'lazy auto call'
$effect=O @('mine_craft_protocol:lazy') $true;A(@($effect.providers)[0].status-eq'completed'-and@($effect.providers)[0].readEffects-eq'lazy_initialization')'effect opt-in'
$fail=O @('mine_craft_protocol:failure','mine_craft_protocol:timeout','mine_craft_protocol:oversized','mine_craft_protocol:invalid') $false; A (@($fail.providers|Where-Object -Property status -ne 'failed').Count -eq 0) 'failure isolation'; A ($null -ne $fail.server.player) 'other domain survived'; A (@($safe.resourceRevisionRefs|Where-Object -Property resourceType -eq 'provider').Count -ge 1) 'provider revision'
[pscustomobject]@{Target=$ExpectedTarget;Safe='PASS';LazyIsolation='PASS';EffectOptIn='PASS';Throw='PASS';Timeout='PASS';Oversized='PASS';SchemaViolation='PASS';OtherDomains='PASS';Result='PASS'}
